<?php
namespace App\Services;
use App\Collaboration\CollaborationResourceRegistry;use Illuminate\Database\Eloquent\Model;use Illuminate\Validation\ValidationException;
final class ResourceAttributionRegistry{private const CREATOR_COLUMNS=['device'=>'created_by','device_template'=>'created_by','dashboard'=>'created_by','automation'=>'created_by','report'=>'created_by','firmware'=>'uploaded_by','location'=>'created_by','webhook'=>'created_by'];public function __construct(private CollaborationResourceRegistry $resources){}public function creatorColumn(string$type):string{$this->resources->definition($type);return self::CREATOR_COLUMNS[$type]??throw ValidationException::withMessages(['resource_type'=>['Creator attribution is unavailable for this resource type.']]);}public function creatorId(string$type,Model$resource):?int{$value=$resource->getAttribute($this->creatorColumn($type));return$value===null?null:(int)$value;}public function supportsContributors(string$type):bool{return(bool)($this->resources->definition($type)->capabilities['revisions']??false);}public function metadata():array{$out=[];foreach(self::CREATOR_COLUMNS as$type=>$column)$out[$type]=['resourceType'=>$type,'creatorSource'=>$column,'contributorSource'=>$this->supportsContributors($type)?'resource_revisions.created_by':null];return$out;}}